				gradeDisplay(2,1000-diff);
			}
			else
			{
				gradeDisplay(1,1000-diff);
			}
			newNoteList[eskey+3][t]=0;
			break;
		}
		nownote[eskey-1]=nownote[eskey-1]-(nownote[eskey-1]>1);
		}
	},999999);
}
